 CREATE TEMPORARY TABLE rrc299_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc299_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc299_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 CREATE TEMPORARY TABLE rrc299_peer_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc299_peer_entries LIKE tradeskill_recipe_entries;
